<script setup lang="ts">
import { Head, useForm, router } from '@inertiajs/vue3'
import { ref } from 'vue'
import ConfirmDialog from '../../Components/ConfirmDialog.vue'
const props=defineProps<{room:any;members:any;state:any;block:any}>()
const tab=ref('members'),confirm=ref(false),readonlyConfirm=ref(false),blockConfirm=ref(false),adminConfirm=ref(false),targetAdmin=ref(props.room.creator||'')
const deletion=useForm({purge:true,force_purge:false,block:true,confirmation:''})
const askDelete=()=>{confirm.value=true}
const remove=()=>{deletion.confirmation=props.room.name||props.room.room_id;deletion.delete('/rooms/'+encodeURIComponent(props.room.room_id))}
</script>
<template><Head :title="room.name||room.room_id"/><v-container fluid class="pa-6"><div class="d-flex align-center mb-5"><v-btn icon="mdi-arrow-right" href="/rooms" variant="text"/><div><h1 class="text-h5">{{ room.name||'اتاق بدون نام' }}</h1><div class="text-caption">{{ room.room_id }}</div></div></div><v-card rounded="xl"><v-tabs v-model="tab"><v-tab value="members">اعضا</v-tab><v-tab value="settings">تنظیمات</v-tab><v-tab value="limits">محدودیت‌ها و State</v-tab></v-tabs><v-divider/><v-window v-model="tab"><v-window-item value="members"><v-card-text><v-list><v-list-item v-for="m in (members.members||[])" :key="m" :title="m"/></v-list></v-card-text></v-window-item><v-window-item value="settings"><v-card-text><v-alert :type="block.block?'warning':'success'" variant="tonal">{{ block.block?'اتاق مسدود است':'اتاق مسدود نیست' }}</v-alert><v-btn class="mt-3" :color="block.block?'success':'warning'" @click="blockConfirm=true">{{ block.block?'رفع مسدودی':'مسدود کردن اتاق' }}</v-btn><v-divider class="my-5"/><v-text-field v-model="targetAdmin" label="شناسه کاربر برای مدیر اتاق"/><v-btn variant="tonal" :disabled="!targetAdmin.startsWith('@')" @click="adminConfirm=true">ارتقای کاربر به مدیر اتاق</v-btn></v-card-text></v-window-item><v-window-item value="limits"><v-card-text><pre class="text-wrap">{{ JSON.stringify(state.state||state,null,2) }}</pre><v-alert type="info" variant="tonal">اعمال این عملیات power levels را تغییر می‌دهد. بازگردانی خودکار تنظیمات قبلی هنوز ارائه نشده است.</v-alert></v-card-text><v-btn color="warning" variant="tonal" class="mt-3" @click="readonlyConfirm=true">فقط‌خواندنی کردن اتاق</v-btn></v-window-item></v-window></v-card><v-card rounded="xl" class="pa-5 mt-5"><v-card-title class="text-error">حذف اتاق</v-card-title><v-card-text><v-switch v-model="deletion.purge" label="پاک‌سازی کامل تاریخچه و داده‌های اتاق"/><v-switch v-model="deletion.force_purge" label="Force purge (فقط در صورت شکست پاک‌سازی عادی)"/><v-switch v-model="deletion.block" label="مسدود کردن اتاق پس از حذف"/><v-btn color="error" @click="askDelete">حذف اتاق</v-btn></v-card-text></v-card><ConfirmDialog v-model="confirm" title="تأیید حذف اتاق" message="برای ادامه باید نام دقیق اتاق را وارد کنید. این عملیات ممکن است غیرقابل‌بازگشت باشد." :required-text="room.name||room.room_id" confirm-text="حذف دائمی" danger @confirm="remove"/><ConfirmDialog v-model="adminConfirm" title="ارتقای مدیر اتاق" message="به این کاربر سطح مدیر اتاق داده می‌شود. ادامه می‌دهید؟" danger @confirm="router.post('/rooms/'+encodeURIComponent(room.room_id)+'/make-admin',{user_id:targetAdmin})"/><ConfirmDialog v-model="blockConfirm" title="تغییر وضعیت مسدودی اتاق" message="وضعیت مسدودی این اتاق تغییر می‌کند. ادامه می‌دهید؟" danger @confirm="router.put('/rooms/'+encodeURIComponent(room.room_id)+'/block',{block:!block.block})"/><ConfirmDialog v-model="readonlyConfirm" title="فقط‌خواندنی کردن اتاق" message="سطح دسترسی ارسال رویدادها تغییر می‌کند و حساب مدیر سرور ممکن است برای اعمال تغییرات به اتاق وارد شود. ادامه می‌دهید؟" danger @confirm="router.post('/rooms/'+encodeURIComponent(room.room_id)+'/read-only')"/></v-container></template>
